+        line-height: 1.05;
+        letter-spacing: -0.055em;
+      }
+
+      .intro {
+        margin: 1rem 0 1.5rem;
+        color: var(--muted);
+        font-size: 1rem;
+      }
+
+      form {
+        display: grid;
+        gap: 1rem;
+      }
+
+      .form-field {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        gap: 0.75rem;
+        align-items: start;
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+        padding: 1rem;
+        background: #f9fbff;
+      }
+
+      .form-field input {
+        width: 1.25rem;
+        height: 1.25rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--primary);
+      }
+
+      .field-text {
+        min-width: 0;
+      }
+
+      label {
+        display: inline-block;
+        font-weight: 750;
+      }
+
+      .required {
+        font-weight: 800;
+      }
+
+      .helper-text {
+        margin: 0.25rem 0 0;
+        color: var(--muted);
+        font-size: 0.9375rem;
+      }
+
+      button {
+        width: 100%;
+        border: 0;
+        border-radius: 999px;
+        padding: 0.875rem 1.25rem;
+        background: var(--primary);
+        color: #ffffff;
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+        transition:
+          background-color 160ms ease,
+          transform 160ms ease;
+      }
+
+      button:hover {
+        background: var(--primary-hover);
+      }
+
+      button:active {
+        transform: translateY(1px);
+        background: var(--primary-active);
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 0;
+        color: var(--success);
+        font-weight: 700;
+      }
+
+      @media (prefers-reduced-motion: reduce) {
+        *,
+        *::before,
+        *::after {
+          transition-duration: 0.01ms !important;
+          scroll-behavior: auto !important;
+        }
+      }
+
+      @media (forced-colors: active) {
+        :root {
+          --background: Canvas;
+          --surface: Canvas;
+          --text: CanvasText;
+          --muted: CanvasText;
+          --border: ButtonBorder;
+          --primary: ButtonText;
+          --primary-hover: ButtonText;
+          --primary-active: ButtonText;
+          --focus: Highlight;
+          --success: CanvasText;
+          --shadow: none;
+        }
+
+        .form-field,
+        .card {
+          border-color: ButtonBorder;
+        }
+
+        button {
+          border: 2px solid ButtonBorder;
+          background: ButtonFace;
+          color: ButtonText;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <div id="root"></div>
+
+    <script>
+      const ConsentField = () => `
+        <div class="form-field">
+          <input
+            type="checkbox"
+            id="terms-consent"
+            name="termsConsent"
+            required
+            aria-describedby="terms-helper"
+          >
+          <div class="field-text">
+            <label for="terms-consent">
+              I agree to the terms of use <span class="required" aria-hidden="true">*</span>
+            </label>
+            <p class="helper-text" id="terms-helper">
+              Required to create your account and continue.
+            </p>
+          </div>
+        </div>
+      `;
+
+      const ConsentForm = () => `
+        <form id="consent-form" novalidate>
+          ${ConsentField()}
+          <button type="submit">Submit agreement</button>
+          <p class="status" id="form-status" aria-live="polite"></p>
+        </form>
+      `;
+
+      const App = () => `
+        <main class="page-shell" id="main-content">
+          <section class="card" aria-labelledby="page-title">
+            <p class="eyebrow">Consent required</p>
+            <h1 id="page-title">Review and accept</h1>
+            <p class="intro">
+              Confirm your agreement to the terms of use before moving forward.
+            </p>
+            ${ConsentForm()}
+          </section>
+        </main>
+      `;
+
+      document.getElementById("root").innerHTML = App();
+
+      const form = document.getElementById("consent-form");
+      const consent = document.getElementById("terms-consent");
+      const status = document.getElementById("form-status");
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        status.textContent = "";
+
+        if (!consent.checked) {
+          consent.setAttribute("aria-invalid", "true");
+          consent.focus();
+          consent.reportValidity();
+          return;
+        }
+
+        consent.removeAttribute("aria-invalid");
+        status.textContent = "Agreement submitted.";
+      });
+
+      consent.addEventListener("change", () => {
+        if (consent.checked) {
+          consent.removeAttribute("aria-invalid");
+        }
+      });
+    </script>
+  </body>
+</html>
*** End Patch
