        display: grid;
        min-height: 100vh;
        padding: 1rem;
        place-items: center;
      }

      .card {
        width: min(100%, 30rem);
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        padding: clamp(1.25rem, 4vw, 2rem);
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--primary);
        font-size: 0.8125rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.25rem);
        line-height: 1.05;
        letter-spacing: -0.055em;
      }

      .intro {
        margin: 1rem 0 1.5rem;
        color: var(--muted);
        font-size: 1rem;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.75rem;
        align-items: start;
        border: 1px solid var(--border);
        border-radius: 1rem;
        padding: 1rem;
        background: #f9fbff;
      }

      .form-field input {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.15rem 0 0;
        accent-color: var(--primary);
      }

      .field-text {
        min-width: 0;
      }

      label {
        display: inline-block;
        font-weight: 750;
      }

      .required {
        font-weight: 800;
      }

      .helper-text {
        margin: 0.25rem 0 0;
        color: var(--muted);
        font-size: 0.9375rem;
      }

      button {
        width: 100%;
        border: 0;
        border-radius: 999px;
        padding: 0.875rem 1.25rem;
        background: var(--primary);
        color: #ffffff;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition:
          background-color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: var(--primary-hover);
      }

      button:active {
        transform: translateY(1px);
        background: var(--primary-active);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--success);
        font-weight: 700;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
